import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { attachControl, setCameraLimits } from "@babylonjs/lite";

function normalizeRadiusRange(
  minDistance: number,
  maxDistance: number
): { lower: number; upper: number } {
  let lower = minDistance;
  let upper = maxDistance;

  if (lower > upper) {
    const tmp = lower;
    lower = upper;
    upper = tmp;
  }

  if (!Number.isFinite(lower)) {
    lower = 0;
  }
  if (!Number.isFinite(upper)) {
    upper = Number.POSITIVE_INFINITY;
  }

  if (lower < 0) {
    lower = 0;
  }
  if (upper < lower) {
    upper = lower;
  }

  return { lower, upper };
}

export function attachLimitedOrbit(
  camera: ArcRotateCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  minDistance: number,
  maxDistance: number
): () => void {
  const { lower, upper } = normalizeRadiusRange(minDistance, maxDistance);

  let detachLimits: (() => void) | undefined;
  try {
    detachLimits = setCameraLimits(
      camera,
      { lowerRadiusLimit: lower, upperRadiusLimit: upper },
      scene
    );
  } catch (error) {
    throw error;
  }

  let detachControls: (() => void) | undefined;
  try {
    detachControls = attachControl(camera, canvas, scene, { keyboard: false });
  } catch (error) {
    detachLimits?.();
    throw error;
  }

  let disposed = false;
  return () => {
    if (disposed) {
      return;
    }
    disposed = true;

    try {
      detachControls?.();
    } finally {
      detachLimits?.();
    }
  };
}
```

I implemented this by using `setCameraLimits` for radius limits and `attachControl` for the library’s standard mouse/touch controls, disabling keyboard controls so no extra canvas listeners are added. I was unsure mainly about whether `setCameraLimits` should be installed before or after `attachControl` for frame-hook ordering, and whether invalid or non-finite min/max distances should be normalized or rejected instead of swapped/sanitized.
